"""Regenerate every plan file that exists on disk from the completed shipped dump, in-process, so no
stale pre-fix plan is left for a setup/content build to pick up."""
import json
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
REPO = os.path.normpath(os.path.join(HERE, ".."))
OUT = os.path.join(REPO, "tools", "unity-rebuild", "out", "unity")
# the REAL dump, regenerated by Unity with the current CatalogDump.cs (complete label_membership)
COMPLETE = os.path.join(OUT, "catalog_dump_shipped.json")
sys.path.insert(0, os.path.join(REPO, "tools", "unity-rebuild"))

import a13f_plan_addressables as planner  # noqa: E402

planner.SHIPPED_DUMP = COMPLETE

groups = []
for name in sorted(os.listdir(OUT)):
    if name.startswith("addressables_plan_") and name.endswith(".json"):
        groups.append(name[len("addressables_plan_"):-len(".json")])
print("plan files on disk:", groups)

for group in groups:
    sys.argv = ["a13f_plan_addressables.py", "--group", group]
    code = planner.main()
    doc = json.load(open(os.path.join(OUT, "addressables_plan_%s.json" % group), encoding="utf-8"))
    lu = doc["labels_used"]
    print(">>> %-9s exit=%d entries=%-6d with_labels=%-6d distinct_labels=%-3d Naninovel=%-6s "
          "membership_complete=%s scheme_entries=%s"
          % (group, code, doc["entry_count"], doc["entries_with_labels"], doc["labels_used_distinct"],
             lu.get("Naninovel"), doc["membership_complete"], doc["shipped_scheme_entries"]))
    print()
